    "apps.seoDesc": "Explore the industrial machinery used in mining, crushing, grinding, screening, and processing minerals supplied by Naveen Minerals.",
    "apps.machine.jaw.name": "Jaw Crusher",
    "apps.machine.jaw.category": "Primary Crushing Equipment",
    "apps.machine.jaw.purpose": "Primary crushing of large rocks and mineral-bearing material into smaller, manageable pieces.",
    "apps.machine.jaw.howItWorks": "Two heavy-duty crushing plates compress large pieces of rock. A fixed plate and a moving swing jaw compress the feed material against each other, breaking large rocks into smaller fragments through high compressive force.",
    "apps.machine.jaw.relevantMaterials": "Limestone, dolomite, feldspar-bearing rock, and quartz-bearing rock, depending on the feed material hardness and primary plant requirements.",
    "apps.machine.jaw.h1": "Primary rock crushing",
    "apps.machine.jaw.h2": "High reduction ratio for raw feed",
    "apps.machine.jaw.h3": "Heavy-duty robust construction",
    "apps.machine.jaw.h4": "Typical first stage in a mineral-processing plant",
    "apps.machine.cone.name": "Impact Crusher & Cone Crusher",
    "apps.machine.cone.category": "Secondary & Tertiary Crushing Equipment",
    "apps.machine.cone.purpose": "Secondary and tertiary crushing to reduce previously crushed rock into smaller aggregate sizes or fine feed for grinding.",
    "apps.machine.cone.howItWorks": "An impact crusher shatters material using high-speed impact forces inside a chamber, while a cone crusher compresses material continuously between an eccentric rotating cone and a concave bowl liner. Note that impact and cone crushers operate on different mechanical principles (impact velocity vs. continuous compression).",
    "apps.machine.cone.relevantMaterials": "Limestone, dolomite, feldspar-bearing rock, and quartz-bearing rock, selected according to material abrasiveness, hardness, and required output shape.",
    "apps.machine.cone.h1": "Secondary particle size reduction",
    "apps.machine.cone.h2": "Crushed stone aggregate preparation",
    "apps.machine.cone.h3": "Cubical product shape generation",
    "apps.machine.cone.h4": "Equipment selection based on rock hardness and abrasiveness",
    "apps.machine.mill.name": "Ball Mill & Grinding Mill",
    "apps.machine.mill.category": "Fine Grinding & Pulverizing Equipment",
    "apps.machine.mill.purpose": "Grinding crushed mineral material into fine powders and micro-pulverized mineral fillers.",
    "apps.machine.mill.howItWorks": "A ball mill uses rotating steel balls or ceramic media inside a rotating cylindrical shell to crush and grind material through impact and attrition. Other grinding mills utilize roller or vertical mill mechanisms depending on target fineness and energy efficiency.",
    "apps.machine.mill.relevantMaterials": "Limestone, calcite, dolomite, feldspar, and quartz. Note: Quartz is abrasive and requires specialized wear-resistant mill liners, grinding media, and controlled operating parameters.",
    "apps.machine.mill.h1": "Fine powder production",
    "apps.machine.mill.h2": "Precise particle size control",
    "apps.machine.mill.h3": "Heavy-duty grinding media and drum rotation",
    "apps.machine.mill.h4": "Wear-resistant engineering for abrasive quartz & feldspar",
    "apps.machine.screen.name": "Vibrating Screen & Powder Classifier",
    "apps.machine.screen.category": "Sizing, Screening & Classification Equipment",
    "apps.machine.screen.purpose": "Separating processed material into precise particle-size ranges and grading finished mineral aggregates.",
    "apps.machine.screen.howItWorks": "Vibrating screens utilize multi-deck mesh screens shaken by eccentric shafts to mechanically sort granular aggregates by particle size. Powder classifiers (such as air classifiers) separate ultra-fine suspended powder particles by balancing centrifugal force and airflow drag.",
    "apps.machine.screen.relevantMaterials": "Stone grit, crushed mineral aggregates, limestone powder, calcite powder, dolomite powder, feldspar powder, and other compatible granular or powdered outputs.",
    "apps.machine.screen.h1": "Particle size separation and grading",
    "apps.machine.screen.h2": "Vibrating decks for coarse stone grit",
    "apps.machine.screen.h3": "Air classification for fine mineral powders",
    "apps.machine.screen.h4": "Screening efficiency and rigorous process control",
    "apps.flow.1.title": "Raw Mineral Feed",
    "apps.flow.1.desc": "Extraction and delivery of quarried raw rock and mineral aggregates.",
    "apps.flow.2.title": "Primary Crushing",
    "apps.flow.2.desc": "Jaw crushers break down large raw boulders into manageable fractions.",
    "apps.flow.3.title": "Secondary Crushing",
    "apps.flow.3.desc": "Impact or cone crushers further reduce particle dimensions if required.",
    "apps.flow.4.title": "Grinding / Milling",
    "apps.flow.4.desc": "Ball mills or grinding mills pulverize material into fine mineral powders.",
    "apps.flow.5.title": "Screening / Classification",
    "apps.flow.5.desc": "Vibrating screens and air classifiers sort materials into precise size grades.",
    "apps.flow.6.title": "Finished Material",
    "apps.flow.6.desc": "Final graded aggregates, chips, and industrial powders ready for supply.",
    "apps.ref.limestone.product": "Limestone Powder",
    "apps.ref.limestone.machinery": "Crushers, grinding mill, air classifier",
    "apps.ref.calcite.product": "Calcite Powder",
    "apps.ref.calcite.machinery": "Suitable crushing equipment, grinding mill, air classifier",
    "apps.ref.dolomite.product": "Dolomite Powder",
    "apps.ref.dolomite.machinery": "Crushers, grinding mill, air classifier",
    "apps.ref.feldspar.product": "Feldspar Powder",
    "apps.ref.feldspar.machinery": "Crushers, suitable grinding mill with wear-resisting liners, classifier",
    "apps.ref.stoneGrit.product": "Stone Grit",
    "apps.ref.stoneGrit.machinery": "Crushers and multi-deck vibrating screens",
    "apps.ref.quartz.product": "Quartz Chips",
    "apps.ref.quartz.machinery": "Suitable heavy-duty crushers and vibrating sizing screens",
    "apps.ref.kolam.product": "Kolam Powder",
    "apps.ref.kolam.machinery": "Depends on raw raw material source and traditional processing method (Note: traditionally decorative floor powder, not an industrial mineral processed through heavy milling)",
