    'home.powdersDesc': 'சுண்ணாம்புப்படி பொடி, கால்சைட் பொடி, டோலமைட் பொடி மற்றும் பெல்ஸ்பார் பொடி ஆகியவை கட்டுமானப் பொருட்கள் தயாரிப்பு, மட்பாண்டங்கள், கண்ணாடி, வர்ணங்கள் மற்றும் பாலிமர் நிரப்பிகளுக்காக வழங்கப்படுகின்றன.',
