    'home.appsDesc': 'எங்கள் பட்டியலில் உள்ள ஒவ்வொரு கனிம தயாரிப்பும் குறிப்பிட்ட உற்பத்தி, கட்டுமானம் அல்லது அலங்கார பயன்பாடுகளுடன் தொடர்புடையது.',
