    'home.whySubtitle': 'நடைமுறை & நேரடி சேவை',
    'home.whyTitle': 'Naveen Minerals ஐ ஏன் தேர்வு செய்ய வேண்டும்',
    'home.whyDesc': 'தமிழ்நாடு மற்றும் இந்தியா முழுவதும் உள்ள வாடிக்கையாளர்களுக்கு தெளிவான தயாரிப்பு தகவல், நேரடியான தொடர்பு மற்றும் நம்பகமான விலைப்புள்ளி ஆதரவில் கவனம் செலுத்துகிறோம்.',
