    'about.intro': 'Naveen Minerals என்பது Namakkal, Tamil Nadu-ஐ மையமாகக் கொண்ட ஒரு கனிம பொருட்கள் நிறுவனமாகும். தயாரிப்பு விவரங்கள் மற்றும் விலைப்புள்ளிகளைத் தேடும் வாடிக்கையாளர்களுக்காக எங்கள் பட்டியல் கனிம பொடிகள், கல் பொருட்கள் மற்றும் குவார்ட்ஸ் தயாரிப்புகளை ஒன்றிணைக்கிறது. உங்கள் தேவைகளைப் பற்றி விவாதிக்கவும் விலைப்புள்ளியைப் பெறவும் எங்களைத் தொடர்பு கொள்ளவும்.',
