    'app.cement-construction.details': 'கட்டுமானப் பொருட்கள் உற்பத்தியாளர்கள் பதப்படுத்தப்பட்ட கனிம பொடிகள் மற்றும் கல் துகள்களைப் பயன்படுத்துகின்றனர்.',
