    'app.paint-coatings.summary': ' கட்டடக்கலை பூச்சுகள் மற்றும் தொழில்துறை மேற்பரப்புகளில் பயன்படுத்தப்படும் நுண்ணிய வெள்ளை கனிம நீட்டிப்புகள்.',
    'app.paint-coatings.details': 'கால்சைட் மற்றும் டோலமைட் பொடிகள் வர்ணம் மற்றும் பூச்சு உருவாக்கங்களில் செயல்பாட்டு கனிம நிரப்பிகளாகப் பயன்படுகின்றன.',
    'app.plastics-rubber.title': '03. பிளாஸ்டிக் மற்றும் ரப்பர்',
    'app.plastics-rubber.summary': 'பாலிமர் கலவை மற்றும் வார்ப்பட ரப்பர் தயாரிப்புகளில் பயன்படுத்தப்படும் பதப்படுத்தப்பட்ட கனிம நிரப்பிகள்.',
    'app.plastics-rubber.details': 'பதப்படுத்தப்பட்ட கால்சைட் மற்றும் சுண்ணாம்பு பொடிகள் பொருத்தமான பிளாஸ்டிக் கலவைகளில் இணைக்கப்பட்டுள்ளன.',
    'app.ceramics-tiles.title': '04. மட்பாண்டங்கள் மற்றும் ஓடுகள் (Ceramics & Tiles)',
    'app.ceramics-tiles.summary': 'செராமிக் டைல்ஸ் உடல்கள் மற்றும் சானிட்டரிவேர் உற்பத்திக்குத் தேவையான கனிம மூலப்பொருட்கள்.',
    'app.ceramics-tiles.details': 'பெல்ஸ்பார் பொடி, குவார்ட்ஸ் சில்லுகள் மற்றும் டோலமைட் பொடி மூலப்பொருட்களாக வழங்கப்படுகின்றன.',
    'app.glass-manufacturing.title': '05. கண்ணாடி உற்பத்தி (Glass Manufacturing)',
    'app.glass-manufacturing.summary': 'கண்ணாடி செயல்முறைகளுக்கான தேர்ந்தெடுக்கப்பட்ட பெல்ஸ்பார், டோலமைட் மற்றும் குவார்ட்ஸ் மூலப்பொருட்கள்.',
    'app.glass-manufacturing.details': 'கண்ணாடி உற்பத்தியாளர்கள் பெல்ஸ்பார் மற்றும் குவார்ட்ஸ் சில்லுகளை மூலப்பொருட்களாகப் பெறுகின்றனர்.',
    'app.decorative-stone.title': '06. தேர்ந்தெடுக்கப்பட்ட அலங்கார & இன்ஜினியர்டு கல் பயன்பாடுகள்',
    'app.decorative-stone.summary': 'இயற்கைக்காட்சி மற்றும் டெராசோ தரை அமைப்புகளுக்கான தரப்படுத்தப்பட்ட கல் துகள்கள் மற்றும் குவார்ட்ஸ் சில்லுகள்.',
    'app.decorative-stone.details': 'கல் கிரைட் மற்றும் குவார்ட்ஸ் சில்லுகள் கட்டடக்கலை தரை அமைப்புகளில் பயன்படுத்தப்படுகின்றன.',
    'app.traditional-kolam.title': '07. பாரம்பரிய கோலம் மற்றும் ரங்கோலி அலங்காரம்',
    'app.traditional-kolam.summary': 'வீடுகள் மற்றும் நிகழ்வுகளில் பாரம்பரிய கோல வடிவங்களை வரைய அர்ப்பணிக்கப்பட்ட அலங்கார வெள்ளை பொடி.',
    'app.traditional-kolam.details': 'தொழில்துறை பயன்பாடுகளிலிருந்து தனித்து வைக்கப்பட்டுள்ள எங்கள் கோலப் பொடி தினசரி மற்றும் திருவிழா தரை வடிவமைப்புகளுக்குப் பயன்படுகிறது.',
