    'productDetail.kolamNote': 'பாரம்பரிய அலங்காரப் பயன்பாட்டிற்கு மட்டுமே: கோலப் பொடி வீடுகள், வாசல்கள் மற்றும் கலாச்சார இடங்களில் பாரம்பரிய கோலங்கள் வரைய மட்டுமே வழங்கப்படுகிறது. இது தொழில்துறை நிரப்பு கனிமம் அல்ல.',
    'productDetail.suitabilityNote': 'பயன்பாட்டுப் பொருத்தம் குறிப்பு: தொழில்துறை மற்றும் உற்பத்தி தேவைகள் செயல்முறைக்கு ஏற்ப மாறுபடும். பொருத்தமான விநியோகத்தை உறுதிப்படுத்த உங்கள் பயன்பாட்டுத் தேவையை விலைப்புள்ளி கோரிக்கையில் குறிப்பிடவும்.',
    'productDetail.viewAllApps': 'அனைத்து தொழில்துறை பயன்பாடுகளையும் காண்க →',
    'productDetail.verifiedDetails': 'சரிபார்க்கப்பட்ட தயாரிப்பு மற்றும் விநியோக விவரங்கள்',
    'productDetail.verifiedDesc': '{name}-க்கான சரிபார்க்கப்பட்ட பட்டியல் தகவல் மற்றும் ஆர்டர் அலகுகளை மதிப்பாய்வு செய்யவும். குறிப்பிட்ட பயன்பாட்டுத் தேவைகள் அல்லது மொத்த விநியோக அட்டவணைகளுக்கு நேரடி விலைப்புள்ளியைக் கோரவும்.',
